  "claim": {
    "component_id": "C028.component",
    "value": "Repeated delays at a particular stage are a temporal pattern to seek.",
    "scope": "A prospective observation category, not an obtained finding or a sufficient bottleneck test by itself.",
    "provenance": {
      "refs": [
