      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping names repeated stage-specific delays as observations to seek and separately specifies a provisional bottleneck rule with explicit evidential limits."
    }
  },
  "signal_basis": {
    "component_id": "C028.signal_basis",
    "value": "Comparable turnaround observations classify equipment status at scheduled starts and track stage-specific counts and delay minutes over time, allowing repeated delays at a stage to be observed.",
    "scope": "Daily review and weekly summaries during the investigation, retaining ambiguous cases and recording completeness; the signal is assumed for this judgment, not reported as obtained.",
    "provenance": {
      "refs": [
        {"source_id": "P007", "role": "SUPPORT"},
