        {"source_id": "P018", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply comparable recording, stage classification, temporal review, completeness tracking and the prospective repeated-delay signal."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C028.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to license this observation-category claim."
    }
  },
  "rationale": "Repeated stage-specific delays across observations constitute a temporal pattern that the described operation can seek. The claim does not assert an established bottleneck, cause or effective intervention.",
  "uncertainty": "Recording limitations can affect recognition of the pattern, but do not undermine this bounded claim under the stipulated assumptions.",
  "anomalies": []
}
